+#define WIN32_LEAN_AND_MEAN
+#include <windows.h>
+
+#include <errno.h>
+#include <process.h>
+#include <stdint.h>
+#include <stdio.h>
+#include <stdlib.h>
+#include <string.h>
+#include <wchar.h>
+
+#define PATH_CAPACITY 32768
+
+static wchar_t *python_script_path(void) {
+    static const wchar_t script_name[] = L"eza_port.py";
+    wchar_t *path = calloc(PATH_CAPACITY, sizeof(*path));
+    wchar_t *backslash;
+    wchar_t *slash;
+    wchar_t *separator;
+    size_t directory_length;
+    DWORD length;
+
+    if (path == NULL) {
+        return NULL;
+    }
+    length = GetModuleFileNameW(NULL, path, PATH_CAPACITY);
+    if (length == 0 || length >= PATH_CAPACITY) {
+        free(path);
+        return NULL;
+    }
+
+    backslash = wcsrchr(path, L'\\');
+    slash = wcsrchr(path, L'/');
+    separator = backslash > slash ? backslash : slash;
+    directory_length = separator == NULL ? 0 : (size_t)(separator - path + 1);
+    if (directory_length + (sizeof(script_name) / sizeof(script_name[0])) > PATH_CAPACITY) {
+        free(path);
+        return NULL;
+    }
+    memcpy(path + directory_length, script_name, sizeof(script_name));
+    return path;
+}
+
+int wmain(int argc, wchar_t **argv) {
+    static const wchar_t python[] = L"python.exe";
+    wchar_t *script = python_script_path();
+    wchar_t **child_argv;
+    intptr_t result;
+    int index;
+
+    if (script == NULL) {
+        fputs("eza launcher: could not locate eza_port.py\n", stderr);
+        return 1;
+    }
+
+    child_argv = calloc((size_t)argc + 2, sizeof(*child_argv));
+    if (child_argv == NULL) {
+        free(script);
+        fputs("eza launcher: out of memory\n", stderr);
+        return 1;
+    }
+    child_argv[0] = (wchar_t *)python;
+    child_argv[1] = script;
+    for (index = 1; index < argc; ++index) {
+        child_argv[index + 1] = argv[index];
+    }
+
+    result = _wspawnvp(_P_WAIT, python, (const wchar_t *const *)child_argv);
+    free(child_argv);
+    free(script);
+    if (result == -1) {
+        fprintf(stderr, "eza launcher: failed to start Python: %s\n", strerror(errno));
+        return 1;
+    }
+    return (int)result;
+}
*** End Patch

